!function(e){function i(i){for(var a,t,o=i[0],m=i[1],d=i[2],g=0,_=[];g<o.length;g++)t=o[g],Object.prototype.hasOwnProperty.call(p,t)&&p[t]&&_.push(p[t][0]),p[t]=0;for(a in m)Object.prototype.hasOwnProperty.call(m,a)&&(e[a]=m[a]);for(c&&c(i);_.length;)_.shift()();return n.push.apply(n,d||[]),r()}function r(){for(var e,i=0;i<n.length;i++){for(var r,t=n[i],o=!0,m=1;m<t.length;m++)r=t[m],0!==p[r]&&(o=!1);o&&(n.splice(i--,1),e=a(a.s=t[0]))}return e}function a(i){if(t[i])return t[i].exports;var r=t[i]={i:i,l:!1,exports:{}};return e[i].call(r.exports,r,r.exports,a),r.l=!0,r.exports}var t={},p={53:0},n=[];a.m=e,a.c=t,a.d=function(e,i,r){a.o(e,i)||Object.defineProperty(e,i,{enumerable:!0,get:r})},a.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},a.t=function(e,i){if(1&i&&(e=a(e)),8&i)return e;if(4&i&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(a.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&i&&"string"!=typeof e)for(var t in e)a.d(r,t,function(i){return e[i]}.bind(null,t));return r},a.n=function(e){var i=e&&e.__esModule?function(){return e.default}:function(){return e};return a.d(i,"a",i),i},a.o=function(e,i){return Object.prototype.hasOwnProperty.call(e,i)},a.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=i,o=o.slice();for(var d=0;d<o.length;d++)i(o[d]);var c=m;n.push([226,0]),r()}({226:function(e,i,r){"use strict";r.r(i);var a=r(0);Object(a.a)("de","army",r(227),r(1))},227:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"轻武器","link":"de_army#de_army_iw"}],"model":"Kar 98K步枪","description":"<p>Kar 98K步枪（简称“K98K”或“98K”）是二战德军的制式步枪，在1935年就开始装备德军，它是沿用了毛瑟Gew步枪的经典旋转后拉式枪机，枪机简单可靠、整枪坚固安全，射击精度较高，且有800米远的射程，因此是早期各参战国众多步枪中的佼佼者。</p><p>Kar 98K步枪是二战期间德军装备最多，使用最广泛的一种步枪。它可加装4倍、6倍光学瞄准镜作狙击步枪用，还可加装枪榴弹发射器发射枪榴弹。但由于其弹仓只有5发的容弹量，且每发射一发子弹就要上一次膛，因此也就限制了射速，同时缺乏火力密度。而在作狙击步枪使用时，每次上膛发出的声响也容易暴露枪手的位置，因此，到了二战中后期，面对苏军与盟军射速较高且具有一定射击精度的半自动与自动步枪时，明显就落在了下风。</p><p>Kar 98K步枪生产数量极大，1935年至1945年一共生产了1400多万支，其中有近13万支为狙击步枪。</p>","part1title":"","part1description":"","part1content":[{"image":"imgs/de/army/de_army_iw98K_11.jpg","description":"<h6>Kar 98K步枪</h6><p></p><p>技术数据：</p><p>口径：7.92毫米；</p><p>全长：1110毫米，枪管长：610毫米，重量：4.1千克；</p><p>枪口初速：760米/秒；</p><p>有效射程：800米；</p><p>弹容量：弹夹5发（弹夹垂直放入枪膛上方，将子弹压下弹仓，弹夹留下，子弹装填完，就可上膛闭锁准备射击了）</p>","caption":""}],"part2title":"战场上的Kar 98K步枪","part2description":"","part2content":[{"image":"imgs/de/army/de_army_iw98K_21.jpg","description":"（图左）德国非洲军团第3侦察分遣队一名手持98K步枪的士兵。（图中）党卫军第13“圣刀”武装山地师一名手持98K步枪的士兵。（图右）党卫军第16“党卫队全国领袖”装甲掷弹兵师一名肩背98K步枪的士兵。","caption":""},{"image":"imgs/de/army/de_army_iw98K_22.jpg","description":"（图左）武装党卫军第8“弗洛里安·盖尔”骑兵师一名肩背98K步枪的士兵。（图右）德军骑兵部队第105骑兵团一名肩背98K步枪的士兵。","caption":""},{"image":"imgs/de/army/de_army_iw98K_23.jpg","description":"（图左）二战战场上一名德军伞兵手持98K步枪向前冲锋。（图右）二战战场上一名手持98K步枪仍保持着战斗姿态的德军负伤士兵。","caption":""},{"image":"imgs/de/army/de_army_iw98K_24.jpg","description":"（图左）二战东线苏联战场，一名德军士兵手持98K步枪弯腰跨越铁丝网出击。（图右）二战东线苏联战场上，一名德军士兵利用楼角作掩护，用98K步枪向敌方目标射击。","caption":""},{"image":"imgs/de/army/de_army_iw98K_25.jpg","description":"1939年9月，德军入侵波兰，一名手持98K步枪的德国武装党卫军第3“骷髅”装甲师士兵正小心地向一个敌方疑似目标靠近。在1939年波兰战役后期，德军已基本粉碎了波兰军队的抵抗，正全力向华沙进发。","caption":""},{"image":"imgs/de/army/de_army_iw98K_26.jpg","description":"1940年6月底，西线法国战场，德军第8步兵师的士兵在巴黎的一个咖啡厅门前休息，98K步枪三支一组枪口向上支撑着一排整齐地放在队伍前面，这也是为了在紧急行动时士兵能迅速有序地拿起步枪集合，可见当时的德军整体军事素质还是不错的。在二战初期，由于冲锋枪与自动步枪尚在研发，所以德军步兵基本上都是配备98K步枪。","caption":""},{"image":"imgs/de/army/de_army_iw98K_27.jpg","description":"1941年夏天，东线苏联战场，在“巴巴罗萨”行动中，德军进展顺利，一队德军士兵正在快速向前挺进，中间一名士兵端着反坦克枪，其它士兵都是端着98K步枪，此时，步兵班中尚少见到MP38/40冲锋枪手。","caption":""},{"image":"imgs/de/army/de_army_iw98K_28.jpg","description":"1941年6月，东线苏联战场，“巴巴罗萨”行动中，隶属德国国防军第18军的一队士兵正利用战斗间隙中作短暂休息，坐在最前面的一名士兵手持的是上了刺刀的98K步枪。","caption":""},{"image":"imgs/de/army/de_army_iw98K_29.jpg","description":"1942年6月，东线苏联战场，德军正在全力进攻塞瓦斯托波尔军事要塞，图为进入要塞郊区的德军，在两名士兵的火力掩护下，另一名士兵端着98K步枪向前跃进。","caption":""},{"image":"imgs/de/army/de_army_iw98K_30.jpg","description":"1942年9月，东线苏联战场，其时德军正在斯大林格勒与苏军展开巷战，一个配备着机枪、冲锋枪与98K步枪的德军战斗小队正在红十月兵工厂工人宿舍的废墟上准备下一步的作战动作。显然，在巷战中，由于受到苏军阻击手的威胁，德军的进攻频频受阻。","caption":""},{"image":"imgs/de/army/de_army_iw98K_31.jpg","description":"1942年，东线苏联战场，一列火车搭载德军部队赶往前线，在敞开车厢中，士兵全部端着98K步枪紧张地向铁道两侧作战斗戒备，以防苏联游击队的突然袭击。1942年秋天，在苏联德军占领区内已有近20万支游击队，他们在莫斯科的游击中央司令部指导下，对德军运输线进行了大量破坏与袭击，给德军的兵员与武器装备运输造成了极大威胁。","caption":""},{"image":"imgs/de/army/de_army_iw98K_32.jpg","description":"1943年，东线苏联战场，在苏军前赴后继的抵抗下，战场态势已开始逆转，德军的进攻受到越来越顽强的抵抗。图中在一名手持98K步枪的德军士兵的掩护下，德军喷火兵使用喷火器向苏军阵地进攻，以期摧毁苏军的坚固工事。","caption":""},{"image":"imgs/de/army/de_army_iw98K_33.jpg","description":"二战后期，东线战场上德军步步退守，在一处森林里的战壕中，一名手持98K狙击步枪的德军士兵正在向进攻的苏军瞄准射击。在德军部队中，有十多万支装上了光学瞄准镜的98K狙击步枪，由于98K步枪有较精确的射击精度，因此其狙击步枪对苏军威胁还是很大的。","caption":""},{"image":"imgs/de/army/de_army_iw98K_34.jpg","description":"二战西线法国战场，一名正进入战壕射击阵地的德国武装党卫军士兵，他手持的98K步枪已上了刺刀，为近战作好准备。","caption":""},{"image":"imgs/de/army/de_army_iw98K_35.jpg","description":"东线苏联战场，神情紧张的德军手持上好刺刀的98K步枪正准备从战壕跃出冲锋，与苏军进行近战博斗。","caption":""},{"image":"imgs/de/army/de_army_iw98K_36.jpg","description":"（图左）二战东线苏联战场上，一名德军中弹后98K步枪脱手飞出的瞬间。（图右）1942年年底，德军在苏联大地上陷入了苦战，两名手持98K步枪的德军士兵神情憔悴，显然对战争已产生恐惧心理。","caption":""},{"image":"imgs/de/army/de_army_iw98K_37.jpg","description":"绘图：二战东线苏联战场上的一个战斗画面，战壕中的德军与苏军正在激战，守备的德军有MG34机枪手、MP40冲锋枪手和98K步枪手，以及负伤士兵与卫生员。","caption":""},{"image":"imgs/de/army/de_army_iw98K_38.jpg","description":"冬季的二战战场，一队德军正在穿过树林转移阵地，队伍中有二名手持98K步枪的士兵，雪地上还躺着敌方的阵亡士兵，可知此处刚经历过一场激烈战斗。","caption":""},{"image":"imgs/de/army/de_army_iw98K_39.jpg","description":"绘图：二战东线战场上一个准备出击的德军战斗小组，小组中配备一名MG34机枪手、一名MP40冲锋枪手和二名98K步枪手。","caption":""},{"image":"imgs/de/army/de_army_iw98K_40.jpg","description":"二战东线苏联战场上，一名德军正在认真地用望远镜观察敌情，为德军98K步枪手确定射击目标。98K步枪本身就有良好的射击精度，再加上枪手利用房屋栅栏作依托，对有经验的士兵来说，射击几乎能百发百中。","caption":""}]}')}});